// Claudeのレスポンス(content[0].text にJSONオブジェクト文字列)からsns_ideaを取り出し、
// post_type/target_persona/source_summaryは共通のまま、4媒体分にファンアウトする
const raw = $input.first().json.content?.[0]?.text ?? '{}';
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  throw new Error('Claude応答のJSONパースに失敗しました: ' + raw.slice(0, 200));
}
const idea = parsed.sns_idea;
const platforms = ['X', 'Instagram', 'Threads', 'LINE'];
return platforms.map(platform => ({
  json: {
    platform,
    post_type: idea.post_type,
    target_persona: idea.target_persona,
    source_summary: idea.source_summary
  }
}));

// Claudeのレスポンス(content[0].text にJSONオブジェクト文字列)からseo_ideaを取り出す
const raw = $input.first().json.content?.[0]?.text ?? '{}';
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  throw new Error('Claude応答のJSONパースに失敗しました: ' + raw.slice(0, 200));
}
const idea = parsed.seo_idea;
return [{
  json: {
    main_keyword: idea.main_keyword,
    target_reader: idea.target_reader,
    differentiation: idea.differentiation
  }
}];
